855: /// Core flight telemetry exporter trait.
856: pub trait FlightExporter {
857:     fn export<W: Write>(&self, dataset: &FlightDataset, writer: &mut W) -> Result<(), ExportError>;
858: }
859: 
860: /// Ergonomic extension methods for all exporters.
861: pub trait FlightExporterExt: FlightExporter {
862:     fn export_to_file<P: AsRef<Path>>(&self, dataset: &FlightDataset, path: P) -> Result<(), ExportError> {
863:         let file = std::fs::File::create(path)?;
864:         let mut writer = std::io::BufWriter::new(file);
865:         self.export(dataset, &mut writer)?;
866:         writer.flush()?;
867:         Ok(())
868:     }
869: 
870:     fn export_to_vec(&self, dataset: &FlightDataset) -> Result<Vec<u8>, ExportError> {
871:         let mut buf = Vec::new();
872:         self.export(dataset, &mut buf)?;
873:         Ok(buf)
874:     }
875: 
876:     fn export_to_string(&self, dataset: &FlightDataset) -> Result<String, ExportError> {
877:         let bytes = self.export_to_vec(dataset)?;
878:         String::from_utf8(bytes).map_err(|e| ExportError::Formatting(e.to_string()))
879:     }
880: }
881: 
882: impl<T: FlightExporter + ?Sized> FlightExporterExt for T {}
883: 
884: #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
885: pub enum ExportFormat {
886:     Csv,
887:     Kml,
888:     Gpx,
889:     GeoJson,
890:     Json,
891: }
892: 
893: impl ExportFormat {
894:     pub const fn file_extension(&self) -> &'static str {
895:         match self {
896:             Self::Csv => "csv",
897:             Self::Kml => "kml",
898:             Self::Gpx => "gpx",
899:             Self::GeoJson => "geojson",
900:             Self::Json => "json",
901:         }
902:     }
903: 
904:     pub const fn mime_type(&self) -> &'static str {
905:         match self {
906:             Self::Csv => "text/csv; charset=utf-8",
907:             Self::Kml => "application/vnd.google-earth.kml+xml",
908:             Self::Gpx => "application/gpx+xml",
909:             Self::GeoJson => "application/geo+json",
910:             Self::Json => "application/json",
911:         }
912:     }
913: }
914: 
915: impl std::str::FromStr for ExportFormat {
916:     type Err = ExportError;
917: 
918:     fn from_str(s: &str) -> Result<Self, Self::Err> {
919:         match s.to_ascii_lowercase().as_str() {
920:             "csv" => Ok(Self::Csv),
921:             "kml" => Ok(Self::Kml),
922:             "gpx" => Ok(Self::Gpx),
923:             "geojson" => Ok(Self::GeoJson),
924:             "json" | "summary" => Ok(Self::Json),
925:             other => Err(ExportError::InvalidData(format!(
926:                 "Unsupported export format '{other}'. Supported formats: csv, kml, gpx, geojson, json"
927:             ))),
928:         }
929:     }
930: }
931: 
932: pub fn export_dataset<W: Write>(
933:     dataset: &FlightDataset,
934:     format: ExportFormat,
935:     writer: &mut W,
936: ) -> Result<(), ExportError> {
937:     match format {
938:         ExportFormat::Csv => CsvExporter::default().export(dataset, writer),
939:         ExportFormat::Kml => KmlExporter::default().export(dataset, writer),
940:         ExportFormat::Gpx => GpxExporter::default().export(dataset, writer),
941:         ExportFormat::GeoJson => GeoJsonExporter::default().export(dataset, writer),
942:         ExportFormat::Json => JsonSummaryExporter::default().export(dataset, writer),
943:     }
944: }
945: ```
