//! Error definitions for the telemetry export engine.

use thiserror::Error;

/// Errors arising from telemetry aggregation, filtering, or format serialization.
#[derive(Debug, Error)]
pub enum ExportError {
    /// Failure originating within core binary decoding or cryptographic engine.
    #[error("Core parsing error: {0}")]
    Core(#[from] flightreader_core::FlightReaderError),

    /// Standard filesystem or network I/O error.
    #[error("I/O error: {0}")]
    Io(#[from] std::io::Error),

    /// JSON serialization or deserialization error.
    #[error("JSON error: {0}")]
    Json(#[from] serde_json::Error),

    /// String formatting or encoding error.
    #[error("Formatting error: {0}")]
    Formatting(String),

    /// Invalid flight dataset or unparseable input.
    #[error("Invalid flight dataset: {0}")]
    InvalidData(String),

    /// Invalid time window bounds passed to filter.
    #[error("Invalid time window: start={start}, end={end} ({reason})")]
    InvalidTimeWindow {
        /// Start boundary representation.
        start: String,
        /// End boundary representation.
        end: String,
        /// Description of validation failure.
        reason: String,
    },

    /// Invalid decimation rate.
    #[error("Invalid decimation rate {rate} Hz: {reason}")]
    InvalidDecimationRate {
        /// Requested rate in Hz.
        rate: f64,
        /// Description of failure.
        reason: String,
    },

    /// XML encoding or schema validation error.
    #[error("XML encoding error: {0}")]
    Xml(String),

    /// Attempted to export an empty dataset when not supported.
    #[error("Cannot export empty dataset")]
    EmptyDataset,

    /// Unrecognized or unsupported export format requested.
    #[error("Unsupported export format: {0}")]
    UnsupportedFormat(String),
}

//! Unified flight telemetry data model for OpenFlightReader Phase 3.
//!
//! Provides synchronized multi-sensor time-series structures (`TelemetryPoint`),
//! mission milestone event representations (`FlightEvent`), session summary metadata
//! (`FlightMetadata`), and the root container (`FlightDataset`).

use serde::{Deserialize, Serialize};

/// A synchronized, multi-sensor flight telemetry point at a discrete instant.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct TelemetryPoint {
    /// Monotonically increasing sequential index of this point in the dataset (0-based).
    pub index: usize,
    /// Absolute UTC Unix timestamp in milliseconds.
    pub timestamp_utc_ms: i64,
    /// ISO 8601 formatted UTC timestamp string (e.g. "2026-10-27T14:32:00.100Z").
    pub timestamp_iso8601: String,
    /// Cumulative elapsed duration in seconds since logging began (monotonically increasing).
    pub elapsed_s: f64,
    /// Official DJI airborne flight timer in seconds (0.0 during pre-takeoff ground idling).
    pub fly_time_s: f64,

    // --- Spatial Position & Vertical Datums ---
    /// WGS84 Geodetic Latitude in decimal degrees (-90.0 to +90.0).
    pub latitude: f64,
    /// WGS84 Geodetic Longitude in decimal degrees (-180.0 to +180.0).
    pub longitude: f64,
    /// Orthometric altitude above Mean Sea Level (MSL) in meters (via EGM2008 / Home datum).
    pub altitude_msl: f64,
    /// Relative altitude Above Ground Level (AGL) in meters relative to takeoff point.
    pub altitude_agl: f64,
    /// Raw barometric relative height from OSD in meters.
    pub altitude_baro: f64,
    /// Ultrasonic / optical flow ground clearance in meters (if sensor active).
    pub vps_height_m: Option<f64>,

    // --- Kinematics & Velocities (NED Frame) ---
    /// Horizontal ground speed in m/s (sqrt(vel_n^2 + vel_e^2)).
    pub ground_speed_mps: f64,
    /// 3D total speed magnitude in m/s (sqrt(vel_n^2 + vel_e^2 + vel_d^2)).
    pub speed_3d_mps: f64,
    /// Climb rate in m/s (-vel_d, positive = ascending).
    pub climb_rate_mps: f64,
    /// Velocity along North axis in m/s (NED frame).
