pub use aggregator::{aggregate_buffer, load_and_aggregate, TelemetryAggregator};
pub use error::ExportError;
pub use exporters::{
    export_dataset, export_to_file, CsvDialect, CsvExporter, CsvOptions, ExportFormat,
    FlightExporter, FlightExporterExt, GeoJsonExporter, GeoJsonOptions, GpxExporter, GpxOptions,
    JsonSummaryExporter, JsonSummaryOptions, KmlExporter, KmlOptions, LineEnding,
};
pub use filter::{filter_dataset, TimeBound, TimeFilter};
pub use model::{FlightDataset, FlightEvent, FlightEventType, FlightMetadata, TelemetryPoint};

/// Commonly used types and traits for flight telemetry export.
pub mod prelude {
    pub use crate::aggregator::{aggregate_buffer, load_and_aggregate, TelemetryAggregator};
    pub use crate::error::ExportError;
    pub use crate::exporters::{
        export_dataset, export_to_file, CsvDialect, CsvExporter, CsvOptions, ExportFormat,
        FlightExporter, FlightExporterExt, GeoJsonExporter, GeoJsonOptions, GpxExporter,
        GpxOptions, JsonSummaryExporter, JsonSummaryOptions, KmlExporter, KmlOptions, LineEnding,
    };
    pub use crate::filter::{filter_dataset, TimeBound, TimeFilter};
    pub use crate::model::{
        FlightDataset, FlightEvent, FlightEventType, FlightMetadata, TelemetryPoint,
    };
}

