//! Shared test fixtures, mock datasets, and schema validation helpers.

use flightreader_export::model::{
    FlightDataset, FlightEvent, FlightEventType, FlightMetadata, TelemetryPoint,
};

/// Generates mock flight datasets for integration and schema testing.
pub mod mock_data {
    use super::*;

    /// 1. Canonical Cruise Flight Dataset:
    /// - 600 points (60.0 seconds at 10 Hz)
    /// - Takeoff from 125.4 m MSL to 223.8 m MSL (98.4 m AGL)
    /// - Seattle Space Needle: 47.606212° N, -122.332145° W
    /// - 4-cell battery starting at 98% (16.4 V) discharging to 85%
    pub fn canonical_cruise_dataset() -> FlightDataset {
        let base_lat = 47.606212;
        let base_lon = -122.332145;
        let takeoff_alt_msl = 125.4;
        let target_alt_agl = 98.4;
        let cruise_speed_mps = 12.5;
        let base_time_ms = 1_729_000_000_000i64; // arbitrary reference UTC epoch

        let mut points = Vec::with_capacity(600);

        for i in 0..600 {
            let elapsed_s = i as f64 * 0.1;
            let fly_time_s = if i < 30 { 0.0 } else { elapsed_s - 3.0 };
            let is_motor_on = i >= 30 && i < 570;

            // Climb phase: 30..150, Cruise: 150..450, Descent: 450..570
            let (agl, vel_d) = if i < 30 {
                (0.0, 0.0)
            } else if i < 150 {
                let frac = (i - 30) as f64 / 120.0;
                (frac * target_alt_agl, -0.82)
            } else if i < 450 {
                (target_alt_agl, 0.0)
            } else if i < 570 {
                let frac = 1.0 - (i - 450) as f64 / 120.0;
                (frac * target_alt_agl, 0.82)
            } else {
                (0.0, 0.0)
            };

            let alt_msl = takeoff_alt_msl + agl;

            // Heading & course turn from 0° (North) to 90° (East)
            let yaw_deg = if i < 150 {
                0.0
            } else if i < 300 {
                (i - 150) as f64 * (90.0 / 150.0)
            } else {
                90.0
            };

            let (vel_n, vel_e, h_speed) = if is_motor_on && i >= 150 && i < 450 {
                let rad = yaw_deg.to_radians();
                (cruise_speed_mps * rad.cos(), cruise_speed_mps * rad.sin(), cruise_speed_mps)
            } else if is_motor_on {
                (1.5, 0.0, 1.5)
            } else {
                (0.0, 0.0, 0.0)
            };

            let speed_3d = (vel_n * vel_n + vel_e * vel_e + vel_d * vel_d).sqrt();

            // Coordinate integration
            let lat = base_lat + (i as f64 * 0.000001);
            let lon = base_lon + (i as f64 * 0.0000015);

            let timestamp_utc_ms = base_time_ms + (elapsed_s * 1000.0).round() as i64;
            let timestamp_iso8601 = chrono::DateTime::from_timestamp_millis(timestamp_utc_ms)
                .map(|dt| dt.to_rfc3339_opts(chrono::SecondsFormat::Millis, true))
                .unwrap_or_else(|| "1970-01-01T00:00:00.000Z".to_string());

            // Battery discharge: 98% -> 85%
            let frac_time = i as f64 / 600.0;
            let battery_pct = (98.0 - frac_time * 13.0).round() as u8;
            let pack_v = 16.4 - frac_time * 1.6;
            let cell_v_mv = ((pack_v / 4.0) * 1000.0).round() as u16;

            let pt = TelemetryPoint {
                index: i,
                timestamp_utc_ms,
                timestamp_iso8601,
                elapsed_s,
                fly_time_s,
                latitude: lat,
                longitude: lon,
                altitude_msl: alt_msl,
                altitude_agl: agl,
                altitude_baro: agl,
                vps_height_m: if agl < 3.0 { Some(agl) } else { None },
                ground_speed_mps: h_speed,
                speed_3d_mps: speed_3d,
                climb_rate_mps: -vel_d,
                vel_n,
                vel_e,
                vel_d,
                course_deg: yaw_deg,
                pitch_deg: if vel_n > 5.0 { -12.4 } else { 0.0 },
                roll_deg: if yaw_deg > 0.0 && yaw_deg < 90.0 { 5.2 } else { 0.0 },
                yaw_deg,
                heading_deg: yaw_deg,
                gimbal_pitch_deg: -45.0,
                gimbal_roll_deg: 0.0,
                gimbal_yaw_deg: 0.0,
                gimbal_mode: "Follow Yaw".to_string(),
                rc_aileron: 0.10,
                rc_elevator: 0.30,
                rc_throttle: 0.50,
                rc_rudder: 0.0,
                rc_mode_switch: "P".to_string(),
                rc_signal_quality: 100,
                battery_pct,
                battery_voltage_mv: (pack_v * 1000.0).round() as u32,
                battery_temp_c: 28.5 + frac_time * 6.0,
                battery_current_a: Some(8.45),
                cell_voltages_mv: vec![cell_v_mv, cell_v_mv - 2, cell_v_mv + 1, cell_v_mv],
                cell_deviation_mv: 3,
                gps_satellites: 18,
                gps_level: 5,
                flight_mode: "P-GPS".to_string(),
                ground_state: if is_motor_on { "Airborne".to_string() } else { "OnGround".to_string() },
                is_motor_on,
                is_failsafe_active: false,
                app_warning: None,
                app_tip: None,
            };
            points.push(pt);
        }

        let metadata = FlightMetadata {
            log_type: "DJI_TXT_V12".to_string(),
            version: 12,
            app_type: Some("DJIFly".to_string()),
            app_version: Some("1.12.8".to_string()),
            drone_type: Some(77),
            aircraft_model: Some("DJI Mavic 3".to_string()),
            aircraft_name: Some("SkyMaster-01".to_string()),
            aircraft_serial: Some("1581F45X210001".to_string()),
            camera_serial: Some("320F98B2".to_string()),
            rc_serial: Some("412A87C1".to_string()),
            battery_serial: Some("089P32D1".to_string()),
            start_time_utc: Some(points[0].timestamp_iso8601.clone()),
            start_time_utc_ms: base_time_ms,
            end_time_utc: Some(points.last().unwrap().timestamp_iso8601.clone()),
            duration_seconds: 59.9,
            flight_duration_seconds: 54.0,
            total_distance_meters: 650.0,
            max_altitude_agl_m: 98.4,
            max_altitude_msl_m: 223.8,
            takeoff_elevation_msl_m: 125.4,
            max_horizontal_speed_mps: 12.5,
            max_vertical_speed_mps: 0.82,
            max_descent_speed_mps: 0.82,
            home_latitude: Some(base_lat),
            home_longitude: Some(base_lon),
            home_altitude_msl: Some(takeoff_alt_msl),
            rth_altitude_m: Some(30.0),
            total_records: 600,
            photos_count: Some(4),
            video_time_seconds: Some(45),
        };

        let events = vec![
            FlightEvent {
                timestamp_utc_ms: base_time_ms + 3000,
                elapsed_s: 3.0,
                flight_time_s: 0.0,
                event_type: FlightEventType::Takeoff,
                description: "Aircraft departed ground surface".to_string(),
                message: "Takeoff".to_string(),
                latitude: Some(base_lat),
                longitude: Some(base_lon),
                altitude_msl: Some(takeoff_alt_msl),
            },
            FlightEvent {
                timestamp_utc_ms: base_time_ms + 57000,
                elapsed_s: 57.0,
                flight_time_s: 54.0,
                event_type: FlightEventType::Landing,
                description: "Aircraft touched down".to_string(),
                message: "Landing".to_string(),
                latitude: Some(base_lat + 0.0006),
                longitude: Some(base_lon + 0.0009),
                altitude_msl: Some(takeoff_alt_msl),
            },
        ];

        FlightDataset {
            metadata,
            points,
            events,
        }
    }

    /// 2. Multi-Segment Transition Dataset:
    /// - 0..200: Cruise (P-GPS, Normal green)
    /// - 200..350: High Wind Warning (Warning orange)
    /// - 350..500: Low Battery Critical RTH (Error red)
    /// - 500..600: Landing
    pub fn multi_segment_dataset() -> FlightDataset {
        let mut ds = canonical_cruise_dataset();

        for (i, p) in ds.points.iter_mut().enumerate() {
            if i >= 200 && i < 350 {
                p.app_warning = Some("High Wind Velocity. Fly with caution.".to_string());
            } else if i >= 350 && i < 500 {
                p.battery_pct = 18;
                p.is_failsafe_active = true;
                p.flight_mode = "Auto-RTH".to_string();
                p.app_warning = Some("Low Battery 20%, RTH Initiated".to_string());
            } else if i >= 500 {
                p.flight_mode = "AutoLanding".to_string();
            }
        }

        ds.events.push(FlightEvent {
            timestamp_utc_ms: ds.points[200].timestamp_utc_ms,
            elapsed_s: 20.0,
            flight_time_s: 17.0,
            event_type: FlightEventType::Warning {
                message: "High Wind Velocity. Fly with caution.".to_string(),
            },
            description: "High Wind Velocity alert".to_string(),
            message: "High Wind".to_string(),
            latitude: Some(ds.points[200].latitude),
            longitude: Some(ds.points[200].longitude),
            altitude_msl: Some(ds.points[200].altitude_msl),
        });

        ds.events.push(FlightEvent {
            timestamp_utc_ms: ds.points[350].timestamp_utc_ms,
            elapsed_s: 35.0,
            flight_time_s: 32.0,
            event_type: FlightEventType::RthTriggered,
            description: "Low Battery Smart RTH initiated".to_string(),
            message: "RTH Triggered".to_string(),
            latitude: Some(ds.points[350].latitude),
            longitude: Some(ds.points[350].longitude),
            altitude_msl: Some(ds.points[350].altitude_msl),
        });

        ds
    }

    /// 3. Boundary & Extremum Flight Dataset:
    /// - Extreme South Pole latitude (-89.9°), Antimeridian longitude (179.999°)
    /// - Negative elevation (-86.5 m MSL in Death Valley depression)
    /// - High speed (150 m/s)
    pub fn boundary_extremum_dataset() -> FlightDataset {
        let mut ds = canonical_cruise_dataset();
        for p in &mut ds.points {
            p.latitude = -89.9;
            p.longitude = 179.999;
            p.altitude_msl = -86.50;
            p.altitude_agl = 20.0;
            p.ground_speed_mps = 150.0;
        }
        ds.metadata.takeoff_elevation_msl_m = -106.5;
        ds.metadata.max_altitude_msl_m = -86.50;
        ds.metadata.home_latitude = Some(-89.9);
        ds.metadata.home_longitude = Some(179.999);
        ds.metadata.home_altitude_msl = Some(-106.5);
        ds
    }

    /// 4. Special Characters & Escaping Stress Dataset:
    /// Quotes, commas, XML entities, unicode emojis, and multiline warnings.
    pub fn special_characters_dataset() -> FlightDataset {
        let mut ds = canonical_cruise_dataset();
        ds.metadata.aircraft_name = Some("DJI 航模 / 飛行記録 🚁 (Mavic 3 Pro - 100% 正常)".to_string());
        ds.metadata.aircraft_model = Some("<Aircraft & Gimbal > 45° 'Special' & Failsafe>".to_string());

        if let Some(p) = ds.points.get_mut(100) {
            p.app_warning = Some("Caution, \"\"obstacle\"\" ahead, abort immediately!".to_string());
            p.app_tip = Some("Tip: <check & verify sensors>".to_string());
        }

        if let Some(p) = ds.points.get_mut(101) {
            p.app_warning = Some("Line 1\nLine 2\r\nLine 3, with \"quotes\" and commas".to_string());
        }

        ds
    }

    /// 5. Empty Dataset: 0 points.
    pub fn empty_dataset() -> FlightDataset {
        FlightDataset {
            metadata: FlightMetadata::default(),
            points: Vec::new(),
            events: Vec::new(),
        }
    }

    /// 6. Stationary high-jitter hover dataset:
    /// Points clustered in 0.05m radius.
    pub fn high_jitter_hover_dataset(count: usize) -> FlightDataset {
        let mut ds = canonical_cruise_dataset();
        ds.points.truncate(count);
        let base_lat = 47.606212;
        let base_lon = -122.332145;
        let base_alt = 150.0;

        for (i, p) in ds.points.iter_mut().enumerate() {
            let offset = (i as f64 * 0.1).sin() * 0.0000005; // ~0.05m jitter
            p.latitude = base_lat + offset;
            p.longitude = base_lon + offset;
            p.altitude_msl = base_alt + offset;
            p.ground_speed_mps = 0.02;
        }
        ds
    }

    /// 7. Dataset with 10-second comms gap for GPX segment splitting.
    pub fn comms_blackout_dataset() -> FlightDataset {
        let mut ds = canonical_cruise_dataset();
        // Insert a 10.0-second time gap between points 100 and 101
        for p in &mut ds.points[101..] {
            p.elapsed_s += 10.0;
            p.timestamp_utc_ms += 10_000;
        }
        ds
    }
}

/// Verification helper primitives for schema validation.
pub mod validator {
    /// Validates XML 1.0 well-formedness and returns the parsed roxmltree Document.
    pub fn parse_xml(content: &str) -> Result<roxmltree::Document<'_>, roxmltree::Error> {
        roxmltree::Document::parse(content)
    }

    /// Verifies that every coordinate in a whitespace-separated KML string conforms to `lon,lat,alt`.
    pub fn assert_kml_coordinates_order(coords_str: &str) {
        for tuple in coords_str.split_whitespace() {
            let parts: Vec<&str> = tuple.split(',').collect();
            assert_eq!(
                parts.len(),
                3,
                "KML coordinate tuple must have 3 components: lon,lat,alt. Found: '{tuple}'"
            );
            let lon: f64 = parts[0].parse().expect("Invalid longitude float");
            let lat: f64 = parts[1].parse().expect("Invalid latitude float");
            let _alt: f64 = parts[2].parse().expect("Invalid altitude float");
            assert!(
                (-180.0..=180.0).contains(&lon),
                "Longitude out of bounds: {lon}"
            );
            assert!(
                (-90.0..=90.0).contains(&lat),
                "Latitude out of bounds: {lat}"
            );
        }
    }

    /// Validates RFC 4180 parsing, CRLF line endings, and equal field counts.
    pub fn validate_rfc4180(bytes: &[u8]) -> (Vec<String>, Vec<Vec<String>>) {
        let text = std::str::from_utf8(bytes).expect("CSV must be valid UTF-8");
        // Verify CRLF on every record boundary (unless empty)
        if !text.is_empty() {
            assert!(
                text.ends_with("\r\n"),
                "CSV must terminate with strict CRLF (\\r\\n)"
            );
        }

        let mut rdr = csv::ReaderBuilder::new()
            .has_headers(true)
            .from_reader(bytes);

        let headers = rdr
            .headers()
            .expect("Failed to read CSV headers")
            .iter()
            .map(|s| s.to_string())
            .collect::<Vec<_>>();

        let mut records = Vec::new();
        for res in rdr.records() {
            let rec = res.expect("CSV row failed RFC 4180 parsing");
            assert_eq!(
                rec.len(),
                headers.len(),
                "Row length mismatch against header: expected {}, found {}",
                headers.len(),
                rec.len()
            );
            records.push(rec.iter().map(|s| s.to_string()).collect());
        }
        (headers, records)
    }
}

