                let ls = placemark.children().find(|n| n.tag_name().name() == "LineString").unwrap();
                let coords_str = ls.children().find(|n| n.tag_name().name() == "coordinates").unwrap().text().unwrap();
                let coords: Vec<String> = coords_str.split_whitespace().map(|s| s.to_string()).collect();
                segment_coordinates.push(coords);
            }
        }
    }

    assert!(
        segment_coordinates.len() >= 2,
        "Segmented dataset must produce multiple placemark segments. Found: {}",
        segment_coordinates.len()
    );

    // Verify boundary vertex continuity: last coordinate of segment N must equal first coordinate of segment N+1
    for i in 0..segment_coordinates.len() - 1 {
        let last_of_current = segment_coordinates[i].last().unwrap();
        let first_of_next = segment_coordinates[i + 1].first().unwrap();
        assert_eq!(
            last_of_current, first_of_next,
            "Shared boundary vertex mismatch between segment {i} and {}: '{last_of_current}' vs '{first_of_next}'",
            i + 1
        );
    }
}

